# Branchdeck shell integration for bash. Generated by Branchdeck; edits are overwritten.
#
# Bash is started as `bash --rcfile <this file> -i`, so it does not read your
# startup files by itself. We load them here, then add a prompt hook that
# reports the last exit code and the current directory to Branchdeck through an
# invisible escape sequence (OSC 6973). Branchdeck strips it from the screen.

# Login environment (on Git for Windows this sets PATH, MSYSTEM and the prompt).
if [ -f /etc/profile ]; then . /etc/profile; fi

if [ -f ~/.bash_profile ]; then
  . ~/.bash_profile
elif [ -f ~/.bashrc ]; then
  . ~/.bashrc
fi

# The nonce lets Branchdeck ignore look-alike sequences printed by programs.
# It is not exported, so child processes never see it.
__bd_nonce="$BRANCHDECK_NONCE"
unset BRANCHDECK_NONCE

__bd_lastpwd=
__bd_cwd=
__bd_prompt() {
  local ec=$?
  if [ "$PWD" != "$__bd_lastpwd" ]; then
    __bd_lastpwd=$PWD
    # Git Bash: report a native Windows path. Only runs after a cd.
    case "$OSTYPE" in
      msys* | cygwin*) __bd_cwd=$(pwd -W 2>/dev/null || printf %s "$PWD") ;;
      *) __bd_cwd=$PWD ;;
    esac
  fi
  printf '\033]6973;P;%s;%s;%s\007' "$__bd_nonce" "$ec" "$__bd_cwd"
  return $ec
}

if [ -n "$__bd_nonce" ]; then
  # Run first so we see the real exit code, and hand it on to any existing hook.
  PROMPT_COMMAND="__bd_prompt${PROMPT_COMMAND:+;$PROMPT_COMMAND}"
fi
